package com.zully.zulrah;

import net.runelite.api.coords.WorldPoint;

/** Fixed world tiles used on the Zul-Andra shore and the Zulrah island. */
public final class ZulrahLocations
{
	public static final WorldPoint START = new WorldPoint(2272, 3077, 0);
	public static final WorldPoint EAST_MELEE_SAFE = new WorldPoint(2274, 3077, 0);
	public static final WorldPoint WEST_MELEE_SAFE = new WorldPoint(2262, 3076, 0);
	public static final WorldPoint CENTRE_MELEE_SAFE_WEST = new WorldPoint(2264, 3072, 0);
	public static final WorldPoint CENTRE_MELEE_SAFE_EAST = new WorldPoint(2272, 3072, 0);
	public static final WorldPoint[] BOAT_TILES = {new WorldPoint(2215,3056,0),new WorldPoint(2215,3057,0),new WorldPoint(2215,3058,0),new WorldPoint(2216,3056,0),new WorldPoint(2216,3057,0),new WorldPoint(2216,3058,0),new WorldPoint(2217,3056,0)};
	private ZulrahLocations() { }
	public static boolean isSuppliedZulAndraBounds(WorldPoint point) { return point != null && point.getPlane() == 0 && point.getX() >= 2181 && point.getX() <= 2212 && point.getY() >= 3041 && point.getY() <= 3072; }
	public static boolean isZulrahArena(WorldPoint point) { return point != null && point.getPlane() == 0 && point.getX() >= 2255 && point.getX() <= 2280 && point.getY() >= 3065 && point.getY() <= 3085; }
	public static boolean isBoatArea(WorldPoint point) { return point != null && point.getPlane() == 0 && point.getX() >= 2214 && point.getX() <= 2218 && point.getY() >= 3055 && point.getY() <= 3059; }
	public static boolean isRelevant(WorldPoint point) { return isSuppliedZulAndraBounds(point) || isBoatArea(point) || isZulrahArena(point); }
}

package com.zully.zulrah;

import com.zully.zulrah.model.*;
import com.zully.zulrah.tracker.*;
import java.awt.*;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import net.runelite.api.*;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

public final class ZulrahPanel extends PluginPanel {
    private static final Color BACKGROUND = ColorScheme.DARK_GRAY_COLOR;
    private static final Color CARD = ColorScheme.DARKER_GRAY_COLOR;
    private static final Color ACCENT = ColorScheme.BRAND_ORANGE;
    private static final Color MUTED = ColorScheme.LIGHT_GRAY_COLOR;
    private static final Color VALUE = Color.WHITE;

    private final EncounterTracker tracker;
    private final SessionTracker session;
    private final Client client;

    private final JLabel status = v();
    private final JLabel rotation = v();
    private final JLabel current = v();
    private final JLabel currentPrayer = v();
    private final JLabel next = v();
    private final JLabel nextPrayer = v();
    private final JLabel then = v();
    private final JLabel thenPrayer = v();
    private final JLabel kills = v();
    private final JLabel deaths = v();
    private final JLabel sessionTime = v();
    private final JLabel xp = v();
    private final JLabel xpHour = v();
    private final JLabel gpGained = v();
    private final JLabel gpSpent = v();
    private final JLabel totalGpGained = v();
    private final JLabel profitHour = v();

    public ZulrahPanel(EncounterTracker t, SessionTracker s, Client c) {
        super(false);
        tracker = t;
        session = s;
        client = c;
        setLayout(new BorderLayout());
        setBackground(BACKGROUND);
        setBorder(new EmptyBorder(10, 10, 10, 10));

        JPanel content = new JPanel();
        content.setOpaque(false);
        content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));

        content.add(header());
        content.add(Box.createVerticalStrut(10));
        content.add(encounter());
        content.add(Box.createVerticalStrut(10));
        content.add(session());

        add(content, BorderLayout.NORTH);
        refresh();
    }

    private JComponent header() {
        JPanel p = new JPanel(new BorderLayout());
        p.setOpaque(false);
        JLabel title = new JLabel("ZULRAH PROFIT TRACKER");
        title.setForeground(ACCENT);
        title.setFont(FontManager.getRunescapeBoldFont());
        p.add(title, BorderLayout.WEST);
        p.add(status, BorderLayout.EAST);
        return p;
    }

    private JComponent encounter() {
        JPanel p = card();
        row(p, "Rotation", rotation);
        section(p, "NOW");
        row(p, "Phase", current);
        row(p, "Prayer", currentPrayer);
        section(p, "NEXT");
        row(p, "Phase", next);
        row(p, "Prayer", nextPrayer);
        section(p, "THEN");
        row(p, "Phase", then);
        row(p, "Prayer", thenPrayer);
        return p;
    }

    private JComponent session() {
        JPanel p = card();
        section(p, "SESSION");
        row(p, "Time in instance", sessionTime);
        p.add(Box.createVerticalStrut(6));
        row(p, "Kills this session", kills);
        row(p, "Deaths this session", deaths);
        p.add(Box.createVerticalStrut(6));
        row(p, "XP gained", xp);
        row(p, "XP / hour", xpHour);
        p.add(Box.createVerticalStrut(6));
        row(p, "GP Gained", gpGained);
        row(p, "GP Spent", gpSpent);
        row(p, "Total GP Gained", totalGpGained);
        p.add(Box.createVerticalStrut(6));
        row(p, "Profit/Hour", profitHour);
        return p;
    }

    private JPanel card() {
        JPanel p = new JPanel();
        p.setBackground(CARD);
        p.setBorder(new EmptyBorder(8, 10, 8, 10));
        p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
        return p;
    }

    private void section(JPanel p, String title) {
        JLabel l = new JLabel(title);
        l.setForeground(ACCENT);
        l.setFont(FontManager.getRunescapeBoldFont());
        l.setBorder(new EmptyBorder(p.getComponentCount() == 0 ? 0 : 8, 0, 4, 0));
        p.add(l);
    }

    private void row(JPanel p, String name, JLabel value) {
        JPanel r = new JPanel(new BorderLayout());
        r.setOpaque(false);
        JLabel l = new JLabel(name);
        l.setForeground(MUTED);
        l.setFont(FontManager.getRunescapeSmallFont());
        value.setForeground(VALUE);
        value.setFont(FontManager.getRunescapeSmallFont());
        r.add(l, BorderLayout.WEST);
        r.add(value, BorderLayout.EAST);
        p.add(r);
    }

    private static JLabel v() {
        return new JLabel("—");
    }

    public void refresh() {
        EncounterState s = tracker.state();
        SessionTracker.Snapshot stats = session.snapshot(System.currentTimeMillis(), xp());
        boolean active = s.status() != EncounterState.Status.INACTIVE;
        status.setText(active ? "ACTIVE" : "STANDBY");
        status.setForeground(active ? ACCENT : MUTED);
        rotation.setText(s.rotation() == null ? (active ? "Detecting" : "—") : "#" + s.rotation());
        current.setText(active ? observed(s) : "Waiting for Zulrah");
        currentPrayer.setText(active ? prayer(tracker.currentPrayer()) : "—");
        ZulrahPhase n = tracker.nextPhase(), later = tracker.phaseAfterNext();
        next.setText(phase(n));
        nextPrayer.setText(prayer(tracker.nextPhasePrayer()));
        then.setText(phase(later));
        thenPrayer.setText(prayer(later == null ? ZulrahPrayer.NONE : later.prayer()));

        sessionTime.setText(formatDuration(stats.instanceTimeMillis));
        kills.setText(number(stats.kills));
        deaths.setText(number(stats.deaths));
        xp.setText(number(stats.xp));
        xpHour.setText(number(stats.xpPerHour));
        gpGained.setText(number(stats.gpGained));
        gpSpent.setText(number(stats.gpSpent));
        totalGpGained.setText(number(stats.netGp));
        profitHour.setText(number(stats.netGpPerHour));
    }

    private String observed(EncounterState s) {
        return s.observedForm() == null ? "Unknown" : s.observedForm().label() + " · " + s.observedPosition();
    }

    private String phase(ZulrahPhase p) {
        return p == null ? "Unknown" : p.form().label() + " · " + p.position();
    }

    private String prayer(ZulrahPrayer p) {
        switch (p) {
            case PROTECT_FROM_MISSILES:
                return "Protect Range";
            case PROTECT_FROM_MAGIC:
                return "Protect Magic";
            case ALTERNATE:
                return "Alternate";
            default:
                return "—";
        }
    }

    private String number(long n) {
        return String.format("%,d", n);
    }

    private String formatDuration(long millis) {
        long seconds = millis / 1000;
        long h = seconds / 3600;
        long m = (seconds % 3600) / 60;
        long s = seconds % 60;
        if (h > 0) {
            return String.format("%d:%02d:%02d", h, m, s);
        }
        return String.format("%02d:%02d", m, s);
    }

    private long xp() {
        long total = 0;
        for (Skill s : new Skill[]{Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE, Skill.HITPOINTS, Skill.RANGED, Skill.MAGIC}) {
            total += client.getSkillExperience(s);
        }
        return total;
    }
}

package com.zully.zulrah;

import com.google.inject.Provides;
import com.zully.zulrah.arena.ArenaPositionResolver;
import com.zully.zulrah.model.*;
import com.zully.zulrah.tracker.*;
import javax.inject.*;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.*;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.*;
import net.runelite.client.ui.*;
import net.runelite.client.game.ItemManager;

@PluginDescriptor(
	name = "Zulrah Profit Tracker",
	description = "Zulrah encounter sidebar navigator and profit tracker",
	tags = {"zulrah", "boss", "pvm", "profit", "tracker", "navigator"},
	enabledByDefault = true
)
@Singleton
public final class ZulrahPlugin extends Plugin
{
	private final ZulrahDetector detector = new ZulrahDetector();
	private final ArenaPositionResolver positions = new ArenaPositionResolver();

	@Inject private Client client;
	@Inject private ZulrahConfig config;
	@Inject private ClientToolbar toolbar;
	@Inject private EncounterTracker tracker;
	@Inject private SessionTracker session;
	@Inject private ItemManager itemManager;

	private NPC zulrah;
	private ZulrahForm lastForm;
	private ZulrahPosition lastPosition;
	private ZulrahPanel panel;
	private NavigationButton button;
	private boolean deathRecorded;
	private WorldPoint lootOrigin;

	private int pendingItemId = -1;
	private long pendingItemClickTime = 0;
	private java.util.Map<Integer, Integer> lastInventory = new java.util.HashMap<>();

	@Provides
	ZulrahConfig provideConfig(ConfigManager manager)
	{
		return manager.getConfig(ZulrahConfig.class);
	}

	@Override
	protected void startUp()
	{
		panel = new ZulrahPanel(tracker, session, client);
		button = NavigationButton.builder()
			.tooltip("Zulrah Profit Tracker")
			.priority(8)
			.icon(ZulrahIcon.create())
			.panel(panel)
			.build();
		toolbar.addNavigation(button);
	}

	@Override
	protected void shutDown()
	{
		if (button != null)
		{
			toolbar.removeNavigation(button);
		}
		reset();
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		NPC npc = event.getNpc();
		if (detector.isZulrah(npc))
		{
			zulrah = npc;
			observe(tracker.state().status() == EncounterState.Status.INACTIVE);
		}
		else if (detector.isSnakeling(npc))
		{
			tracker.snakelingSpawned(npc.getIndex());
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		NPC npc = event.getNpc();
		if (npc == zulrah)
		{
			if (deathRecorded)
			{
				reset();
			}
			else
			{
				zulrah = null;
				lastForm = null;
				lastPosition = null;
			}
		}
		else if (detector.isSnakeling(npc))
		{
			tracker.snakelingDespawned(npc.getIndex());
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		long now = System.currentTimeMillis();
		session.startIfNeeded(now, combatExperience());
		boolean inInstance = client.isInInstancedRegion();
		if (inInstance && client.getMapRegions() != null)
		{
			inInstance = false;
			for (int regionId : client.getMapRegions())
			{
				if (regionId == 9007 || regionId == 9008)
				{
					inInstance = true;
					break;
				}
			}
		}
		session.tickInstanceTimer(now, inInstance);

		if (zulrah == null)
		{
			for (NPC npc : client.getNpcs())
			{
				if (detector.isZulrah(npc))
				{
					zulrah = npc;
					observe(tracker.state().status() == EncounterState.Status.INACTIVE);
					break;
				}
			}
		}
		else
		{
			observe(false);
		}

		if (panel != null)
		{
			panel.refresh();
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		trackPendingConsumableClick(event);
	}

	private void trackPendingConsumableClick(MenuOptionClicked event)
	{
		int itemId = event.getItemId();
		if (itemId <= 0) return;

		ItemComposition def = itemManager.getItemComposition(itemId);
		if (def == null) return;
		String name = def.getName();
		if (name == null) return;
		String lowerName = name.toLowerCase(java.util.Locale.ROOT);

		String option = event.getMenuOption() != null ? event.getMenuOption().toLowerCase(java.util.Locale.ROOT) : "";

		// Ignore bank deposit / store actions so depositing supplies doesn't count as spending
		if (option.startsWith("deposit") || option.startsWith("store")) return;

		boolean isEat = "eat".equals(option);
		boolean isDrink = "drink".equals(option);
		boolean isTeleport = "teleport".equals(option) || "break".equals(option) || "read".equals(option);

		if (!isEat && !isDrink && !isTeleport)
		{
			String[] actions = def.getInventoryActions();
			if (actions != null)
			{
				for (String act : actions)
				{
					if (act != null)
					{
						String lowerAct = act.toLowerCase(java.util.Locale.ROOT);
						if (lowerAct.equals(option))
						{
							if ("eat".equals(lowerAct)) isEat = true;
							else if ("drink".equals(lowerAct)) isDrink = true;
							else if ("teleport".equals(lowerAct) || "break".equals(lowerAct) || "read".equals(lowerAct)) isTeleport = true;
						}
					}
				}
			}
		}

		if (isEat || isDrink || isTeleport || lowerName.contains("zul-andra teleport"))
		{
			pendingItemId = itemId;
			pendingItemClickTime = System.currentTimeMillis();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.INVENTORY.getId()) return;
		ItemContainer container = event.getItemContainer();
		if (container == null) return;

		java.util.Map<Integer, Integer> currentInventory = new java.util.HashMap<>();
		for (Item item : container.getItems())
		{
			if (item != null && item.getId() > 0)
			{
				currentInventory.put(item.getId(), currentInventory.getOrDefault(item.getId(), 0) + item.getQuantity());
			}
		}

		if (!lastInventory.isEmpty() && (System.currentTimeMillis() - pendingItemClickTime < 3000))
		{
			for (java.util.Map.Entry<Integer, Integer> entry : lastInventory.entrySet())
			{
				int id = entry.getKey();
				int oldQty = entry.getValue();
				int newQty = currentInventory.getOrDefault(id, 0);

				if (oldQty > newQty && id == pendingItemId)
				{
					int consumedQty = oldQty - newQty;
					ItemComposition def = itemManager.getItemComposition(id);
					if (def != null)
					{
						String name = def.getName();
						if (name != null)
						{
							String lowerName = name.toLowerCase(java.util.Locale.ROOT);
							if (isTrackedConsumable(def, lowerName))
							{
								long itemPrice = itemManager.getItemPrice(id);
								long unitCost = calculateItemCost(lowerName, itemPrice);
								if (unitCost > 0)
								{
									session.recordItemSpent(unitCost * consumedQty);
								}
							}
						}
					}
					pendingItemId = -1; // Reset pending action once verified
				}
			}
		}

		lastInventory = currentInventory;
	}

	private boolean isTrackedConsumable(ItemComposition def, String lowerName)
	{
		if (lowerName.equals("zul-andra teleport") || lowerName.contains("zul-andra teleport"))
		{
			return true;
		}
		if (lowerName.matches(".*\\([1-4]\\)$"))
		{
			return true;
		}
		String[] actions = def.getInventoryActions();
		if (actions != null)
		{
			for (String act : actions)
			{
				if (act != null)
				{
					String lowerAct = act.toLowerCase(java.util.Locale.ROOT);
					if ("eat".equals(lowerAct) || "drink".equals(lowerAct))
					{
						return true;
					}
				}
			}
		}
		return false;
	}

	private long calculateItemCost(String lowerName, long itemPrice)
	{
		if (lowerName.equals("zul-andra teleport") || lowerName.contains("zul-andra teleport"))
		{
			return itemPrice;
		}
		java.util.regex.Matcher matcher = java.util.regex.Pattern.compile(".*\\((\\d)\\)$").matcher(lowerName);
		if (matcher.matches())
		{
			int doses = Integer.parseInt(matcher.group(1));
			if (doses > 0)
			{
				return Math.max(1, itemPrice / doses);
			}
		}
		return itemPrice;
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (event.getActor() == zulrah)
		{
			recordDeathIfNeeded();
		}
		else if (event.getActor() == client.getLocalPlayer())
		{
			session.recordDeath();
		}
	}

	@Subscribe
	public void onItemSpawned(ItemSpawned event)
	{
		WorldPoint location = event.getTile().getWorldLocation();
		if (!session.acceptsLoot(System.currentTimeMillis()) ||
			(!ZulrahLocations.isZulrahArena(location) && (lootOrigin == null || location.distanceTo2D(lootOrigin) > 8)))
		{
			return;
		}
		TileItem item = event.getItem();
		session.recordLoot((long) item.getQuantity() * itemManager.getItemPrice(item.getId()));
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		if (event.getActor() == zulrah && zulrah.getAnimation() != -1)
		{
			tracker.attackObserved();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.LOGIN_SCREEN_AUTHENTICATOR || state == GameState.CONNECTION_LOST || state == GameState.HOPPING)
		{
			reset();
		}
	}

	private void observe(boolean starting)
	{
		if (zulrah == null) return;
		ZulrahForm form = ZulrahForm.fromNpcId(zulrah.getId());
		if (form == null) form = starting ? ZulrahForm.SERPENTINE : lastForm;
		if (form == null) return;

		if (starting)
		{
			deathRecorded = false;
			lootOrigin = null;
			if (positions.resolveBoss(zulrah.getWorldLocation()) == ZulrahPosition.UNKNOWN)
			{
				positions.anchor(zulrah.getWorldLocation());
			}
		}

		ZulrahPosition position = positions.resolveBoss(zulrah.getWorldLocation());
		if (starting)
		{
			tracker.start(form, position);
		}
		else if (form != lastForm || position != lastPosition)
		{
			tracker.observePhase(form, position);
		}

		lastForm = form;
		lastPosition = position;
	}

	private void recordDeathIfNeeded()
	{
		if (!deathRecorded)
		{
			deathRecorded = true;
			lootOrigin = zulrah == null ? null : zulrah.getWorldLocation();
			session.recordKill(System.currentTimeMillis());
		}
	}

	private long combatExperience()
	{
		long total = 0;
		for (Skill skill : new Skill[]{Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE, Skill.HITPOINTS, Skill.RANGED, Skill.MAGIC})
		{
			total += client.getSkillExperience(skill);
		}
		return total;
	}

	private void reset()
	{
		tracker.reset();
		positions.reset();
		zulrah = null;
		lastForm = null;
		lastPosition = null;
		if (panel != null)
		{
			panel.refresh();
		}
	}
}

package com.zully.zulrah.arena;
import com.zully.zulrah.model.ZulrahPosition;
import net.runelite.api.coords.WorldPoint;
/** Resolves logical locations relative to the detected instance, never absolute map coordinates. */
public final class ArenaPositionResolver {
    private static final int FIRST_WAVE_NORTH_EAST_OFFSET = 6;
    private ZulrahArena arena;
    public void anchor(WorldPoint center){if(center!=null) arena=new ZulrahArena(center);}
    public ZulrahPosition resolveBoss(WorldPoint point){if(arena==null||point==null)return ZulrahPosition.UNKNOWN; int dx=point.getX()-arena.center().getX(),dy=point.getY()-arena.center().getY(); if(Math.abs(dx)<=2&&Math.abs(dy)<=2)return ZulrahPosition.CENTER; return Math.abs(dx)>Math.abs(dy)?(dx>0?ZulrahPosition.EAST:ZulrahPosition.WEST):(dy>0?ZulrahPosition.NORTH:ZulrahPosition.SOUTH);}
    public ArenaTile target(ZulrahPosition position){if(arena==null)return null; int dx=0,dy=0; switch(position){case EAST:dx=5;break;case WEST:dx=-5;break;case SOUTH:dy=-5;break;case NORTH:dy=5;break;default:break;} return new ArenaTile(position,new WorldPoint(arena.center().getX()+dx,arena.center().getY()+dy,arena.center().getPlane()));}
    /** The far north-east staging square requested for Zulrah's opening phase. */
    public ArenaTile firstWaveStand(){return arena==null?null:new ArenaTile(ZulrahPosition.NORTH,new WorldPoint(arena.center().getX()+FIRST_WAVE_NORTH_EAST_OFFSET,arena.center().getY()+FIRST_WAVE_NORTH_EAST_OFFSET-1,arena.center().getPlane()));}
    /** Standard pillar/safe squares, expressed relative to the detected centre spawn. */
